const body = $input.item.json.body || $input.item.json;
return {
  json: {
    job_id: body.job_id,
    video_id: body.video_id,
    brief: body.brief || {},
    prompt_version: 'script/v1'
  }
};

const input = $input.item.json;
const brief = input.brief || {};
const duration = brief.targetDurationSeconds || 30;

const script = {
  videoId: input.video_id,
  title: brief.workingTitle || 'سيناريو الفيديو',
  hook: brief.hookStrategy || 'هل ترغب في معرفة السر؟',
  fullNarration: 'هل ترغب في معرفة السر؟ إليك أهم النقاط الأساسية لتحقيق هدفك بسرعة وكفاءة. أولاً: التخطيط المنظم. ثانياً: الاستمرارية في التنفيذ. تابعنا للمزيد من المحتوى المميز!',
  estimatedWordCount: Math.round(duration * 2.2),
  estimatedDurationSeconds: duration,
  language: brief.language || 'ar',
  callToAction: brief.callToAction || 'شارك الفيديو مع أصدقائك',
  sections: [
    {
      id: 'sec_1',
      title: 'الخطاف الافتتاحي',
      narration: 'هل ترغب في معرفة السر؟',
      targetDurationSeconds: Math.round(duration * 0.2)
    },
    {
      id: 'sec_2',
      title: 'المحتوى الأساسي',
      narration: 'إليك أهم النقاط الأساسية لتحقيق هدفك بسرعة وكفاءة: التخطيط والاستمرارية.',
      targetDurationSeconds: Math.round(duration * 0.6)
    },
    {
      id: 'sec_3',
      title: 'الخاتمة والدعوة للإجراء',
      narration: 'تابعنا للمزيد من المحتوى المميز!',
      targetDurationSeconds: Math.round(duration * 0.2)
    }
  ]
};

return {
  json: {
    job_id: input.job_id,
    video_id: input.video_id,
    stage: 'SCRIPT_GENERATION',
    script: script
  }
};
